from math import gcd
from sympy import isprime, factorint
def carm(n):
    return not isprime(n) and n > 1 and all(pow(a,n-1,n) == 1 for a in range(1,n) if gcd(a,n) == 1)
assert [n for n in range(2,1730) if carm(n)] == [561,1105,1729]
for n in (561,1105,1729):
    f = factorint(n)
    assert all(e == 1 for e in f.values()) and all((n-1) % (p-1) == 0 for p in f)
assert [pow(2,35*2**k,561) for k in range(5)] == [263,166,67,1,1]
assert gcd(66,561) == 33 and gcd(68,561) == 17 and 67**2 == 8*561+1

from math import gcd
from sympy import isprime, factorint
def kors(n):
    f = factorint(n)
    return all(e == 1 for e in f.values()) and all((n-1) % (p-1) == 0 for p in f)
car = []
for n in range(4,20000):
    if isprime(n): continue
    if kors(n): car.append(n)
def carm(n):
    return all(pow(a,n-1,n) == 1 for a in range(2,n) if gcd(a,n) == 1)
for n in car: assert carm(n)
for n in range(4,3000):
    if not isprime(n): assert carm(n) == kors(n)

from sympy import primitive_root, prime
import math
def bsgs(g,h,p):
    N = p-1; m = math.isqrt(N-1)+1
    table = {}
    e = 1
    for j in range(m):
        table.setdefault(e,j); e = e*g % p
    f = pow(g,-m,p); y = h
    for i in range(m):
        if y in table: return i*m + table[y]
        y = y*f % p
    return None
for p in [prime(k) for k in range(5,80)]:
    g = primitive_root(p)
    for h in range(1,p):
        x = bsgs(g,h,p)
        assert x is not None and pow(g,x,p) == h

blocks.body:
A proof would give, at once:

- the sharp prime number theorem $\pi(x)=\operatorname{li}(x)+O(\sqrt x\log x)$;
- primes in every interval $[x,x+C\sqrt x\log x]$ for large $x$ (Cramér, 1920, gave the corresponding bound $p_{n+1}-p_n=O(\sqrt{p_n}\log p_n)$ under RH);
- the Lindelöf hypothesis $\zeta(\tfrac12+it)=O(|t|^\varepsilon)$, which follows from RH (see [[lindelof]]);
- $M(x)=O(x^{1/2+\varepsilon})$ for the Mertens function, and many other sharp estimates for arithmetic functions.

Hundreds of published theorems begin "Assume RH"; a proof would make them unconditional. A disproof, by a single zero off the line, would show that the error in the prime number theorem has size $x^\Theta$ with $\Theta>\tfrac12$ and would change the expected picture of the primes considerably.

