import math
from sympy import primerange
x = 10**6
s = {1:0.0, 3:0.0}
for p in primerange(3, x+1):
    pk = p
    while pk <= x:
        s[pk % 4] += math.log(p); pk *= p
assert abs(s[1] - 499368.8) < 0.1 and abs(s[3] - 500204.6) < 0.1
assert abs(s[1] - x/2 + 631) < 1 and abs(s[3] - x/2 - 205) < 1
assert abs(s[1]-x/2) < 1000 and abs(s[3]-x/2) < 1000
assert abs(math.sqrt(x)*math.log(x)**2 - 1.9e5) < 0.01e5
th = {1:0.0, 3:0.0}
for p in primerange(3, x+1):
    th[p % 4] += math.log(p)
assert th[3] > th[1]

import cmath, math
from sympy import primitive_root, primerange
def psi_char(x, q, g, k):
    ind = {pow(g, j, q): j for j in range(q-1)}
    s = 0
    for p in primerange(2, x+1):
        pk = p
        while pk <= x:
            r = pk % q
            if r != 0:
                s += cmath.exp(2j*math.pi*k*ind[r]/(q-1))*math.log(p)
            pk *= p
    return s, ind
for q in (5, 7):
    g = primitive_root(q)
    x = 2000
    vals = []
    for k in range(q-1):
        v, ind = psi_char(x, q, g, k); vals.append(v)
    for a in range(1, q):
        direct = sum(math.log(p) for p in primerange(2, x+1) for e in range(1, 20) if p**e <= x and p**e % q == a)
        via = sum(cmath.exp(-2j*math.pi*k*ind[a]/(q-1))*vals[k] for k in range(q-1))/(q-1)
        assert abs(via - direct) < 1e-6

import cmath, math
for p in (2, 3):
    for k in range(-5, 6):
        s = 2j*math.pi*k/math.log(p)
        assert abs(1 - p**(-s)) < 1e-12
for z in (1j, -1, 1, cmath.exp(0.7j), -1j):
    for p in (2, 3, 5, 7):
        for t in (0.0, 1.0, 13.7, 100.0):
            for sig in (0.1, 0.5, 0.9):
                assert abs(1 - z*p**(-(sig+1j*t))) > 1 - p**(-sig) - 1e-12
